import React, { useEffect, useState } from "react";
import axios from "axios";
import ListingCard from "./ListingCard"; // make sure the path is correct
import "../App.css";

export default function ViewListings() {
  const [listings, setListings] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchListings = async () => {
      try {
        const token = localStorage.getItem("token"); // JWT token stored on login
        const res = await axios.get("http://localhost:5000/api/listings", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setListings(res.data);
      } catch (err) {
        console.error("Error fetching listings:", err);
        alert("Failed to fetch listings. Please try again.");
      } finally {
        setLoading(false);
      }
    };

    fetchListings();
  }, []);

  return (
    <div className="view-listings-container" style={{ padding: "40px 20px" }}>
      <h2 className="page-title" style={{ textAlign: "center", marginBottom: "30px" }}>
        My Listings
      </h2>

      {loading ? (
        <p style={{ textAlign: "center" }}>Loading your listings...</p>
      ) : listings.length === 0 ? (
        <p style={{ textAlign: "center" }}>You have not created any listings yet.</p>
      ) : (
        <div
          className="listings-grid"
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
            gap: "20px",
            justifyItems: "center",
          }}
        >
          {listings.map((listing) => (
            <ListingCard key={listing._id} listing={listing} />
          ))}
        </div>
      )}
    </div>
  );
}
